import{_ as r}from"./chunks/dexi_5.Dd2VtMp7.js";import{_ as o,o as a,c as t,al as i}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"DroneBlocks DEXI 5","description":"","frontmatter":{},"headers":[],"relativePath":"ko/complete_vehicles_mc/droneblocks_dexi.md","filePath":"ko/complete_vehicles_mc/droneblocks_dexi.md"}'),n={name:"ko/complete_vehicles_mc/droneblocks_dexi.md"};function l(s,e,c,d,p,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="droneblocks-dexi-5" tabindex="-1">DroneBlocks DEXI 5 <a class="header-anchor" href="#droneblocks-dexi-5" aria-label="Permalink to &quot;DroneBlocks DEXI 5&quot;">​</a></h1><p>The <a href="https://droneblocks.io/program/dexi-5-px4-stem-drone-kit/" target="_blank" rel="noreferrer">DEXI 5</a> is an NDAA-compliant PX4 STEM and development drone kit from <a href="https://droneblocks.io/" target="_blank" rel="noreferrer">DroneBlocks</a>, designed to take students, hobbyists, and PX4 developers from unboxing to writing autonomous code with no technical barrier.</p><p>DEXI 5 is an <a href="./../dev_kits/">Official PX4 Developer Kit</a>.</p><p><img src="'+r+'" alt="DroneBlocks DEXI 5 in flight"></p><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>DEXI 5 is built around an all-in-one flight controller running PX4, developed in collaboration with <a href="https://arkelectron.com/" target="_blank" rel="noreferrer">ARK Electronics</a>, with integrated optical flow sensing for GPS-denied indoor flight. A Raspberry Pi compute module acts as the companion computer, with a Pi camera and accessible GPIO pins for sensors, servos, and other payloads (up to about 225 g).</p><p>Assembly is modular, solder-free, and plug-and-play, and is itself part of the learning experience: building the vehicle teaches the aerodynamics, mechanics, and electronics behind it.</p><p>All critical electronic components are manufactured in the United States, meeting NDAA Section 848 requirements.</p><h2 id="software-and-curriculum" tabindex="-1">Software and Curriculum <a class="header-anchor" href="#software-and-curriculum" aria-label="Permalink to &quot;Software and Curriculum&quot;">​</a></h2><p>The kit ships with a full project-based curriculum on <a href="https://learn.droneblocks.io/" target="_blank" rel="noreferrer">learn.droneblocks.io</a> covering:</p><ul><li>DroneBlocks visual (block-based) programming</li><li>Python scripting with <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a></li><li><a href="./../ros2/">ROS 2</a> development, including projects such as AprilTag detection</li><li>Computer vision with OpenCV using the onboard Pi camera</li></ul><p>Community support is available on the <a href="https://community.droneblocks.io/" target="_blank" rel="noreferrer">DroneBlocks forum</a>.</p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><ul><li><a href="https://droneblocks.io/program/dexi-5-px4-stem-drone-kit/" target="_blank" rel="noreferrer">DroneBlocks DEXI 5</a> (single kits and classroom packs)</li></ul>',14)])])}const k=o(n,[["render",l]]);export{f as __pageData,k as default};
